import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 1_000_000_007L

fun modPow(base: Long, exp: Long): Long {
    var b = base % MOD
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) == 1L) res = (res * b) % MOD
        b = (b * b) % MOD
        e = e shr 1
    }
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val x = st.nextToken().toInt()
    val pos = st.nextToken().toInt()

    var less = x - 1          // numbers < x
    var greater = n - x       // numbers > x

    var left = 0
    var right = n
    var ways = 1L

    while (left < right) {
        val mid = (left + right) / 2
        if (mid <= pos) {
            if (mid == pos) {
                left = mid + 1
            } else {
                // must place a number < x
                if (less <= 0) {
                    println(0)
                    return
                }
                ways = (ways * less) % MOD
                less--
                left = mid + 1
            }
        } else {
            // mid > pos: must place a number > x
            if (greater <= 0) {
                println(0)
                return
            }
            ways = (ways * greater) % MOD
            greater--
            right = mid
        }
    }

    val remaining = (less + greater).toLong()
    ways = (ways * modPow(remaining % MOD, remaining)) % MOD

    println(ways % MOD)
}

